const cfg = $('Config').first().json;
const num = (v) => { const n = Number(v); return isFinite(n) ? n : 0; };
const uniq = (rows, key) => { const seen = {}; const out = []; rows.forEach(r => { const k = String(r[key] || '').trim(); if (k && !seen[k]) { seen[k] = true; out.push(r); } }); return out; };
const pol = uniq($('Read Policy').all().map(i => i.json).filter(r => r && r.policy_key), 'policy_key');
const prods = uniq($('Read Products').all().map(i => i.json).filter(r => r && r.sku), 'sku');
const orders = uniq($('Read Orders').all().map(i => i.json).filter(r => r && r.order_id), 'order_id');
const custs = uniq($('Read Customers').all().map(i => i.json).filter(r => r && r.customer_id), 'customer_id');
const reqs = uniq($('Read Return Requests').all().map(i => i.json).filter(r => r && r.request_id), 'request_id');
const logs = uniq($('Read Decision Log').all().map(i => i.json).filter(r => r && r.decision_id), 'decision_id');
const P = {};
pol.forEach(r => { P[String(r.policy_key).trim()] = r.policy_value; });
const prodBy = {};
prods.forEach(r => { prodBy[String(r.sku).trim()] = r; });
const orderBy = {};
orders.forEach(r => { orderBy[String(r.order_id).trim()] = r; });
const custBy = {};
custs.forEach(r => { custBy[String(r.customer_id).trim()] = r; });
const dedupe = (String(cfg.dedupe_enabled) === 'true') || (cfg.dedupe_enabled === true);
const done = {};
logs.forEach(l => { if (String(l.decision || '').trim() === 'rto_save_sent') { return; } done[String(l.request_id || '').trim()] = true; });
const TZ = num(cfg.tz_offset_minutes) || 330;
const pad = (n) => String(n).padStart(2, '0');
const now = new Date(Date.now() + TZ * 60000);
const fd = (d) => d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
const today = fd(now);
const stamp = now.getUTCFullYear() + pad(now.getUTCMonth() + 1) + pad(now.getUTCDate()) + pad(now.getUTCHours()) + pad(now.getUTCMinutes());
const tMs = Date.parse(today + 'T00:00:00Z');
const daysBetween = (ds) => { const t = Date.parse(String(ds || '').trim().slice(0, 10) + 'T00:00:00Z'); if (isNaN(t)) { return -1; } return Math.round((tMs - t) / 86400000); };
const issues = [];
let skipped = 0;
const open = [];
reqs.forEach(r => {
  const rid = String(r.request_id).trim();
  if (String(r.status || '').toLowerCase().trim() === 'processed') { skipped += 1; return; }
  if (dedupe && done[rid]) { skipped += 1; return; }
  const o = orderBy[String(r.order_id || '').trim()];
  if (!o) { issues.push('No order found for request ' + rid); return; }
  const p = prodBy[String(o.sku || '').trim()] || {};
  const c = custBy[String(r.customer_id || '').trim()] || {};
  const sinceDelivery = daysBetween(o.delivery_date);
  const transitDays = (String(o.ship_date || '') && String(o.delivery_date || '')) ? Math.round((Date.parse(String(o.delivery_date).slice(0, 10) + 'T00:00:00Z') - Date.parse(String(o.ship_date).slice(0, 10) + 'T00:00:00Z')) / 86400000) : -1;
  open.push({ request_id: rid, received_at: String(r.received_at || ''), raw_text: String(r.raw_text || ''), images_attached: String(r.images_attached || 'no').toLowerCase().trim(),
    order_id: String(o.order_id), sku: String(o.sku), product_name: String(o.product_name || p.name || ''), category: String(p.category || ''), returnable: String(p.returnable || 'yes').toLowerCase().trim(),
    order_value: num(o.order_value_inr), cogs: num(p.cogs_inr), payment_mode: String(o.payment_mode || '').toLowerCase().trim(), courier: String(o.courier || ''), pincode: String(o.pincode || ''), city: String(o.city || ''),
    delivery_date: String(o.delivery_date || ''), days_since_delivery: sinceDelivery, transit_days: transitDays,
    customer_id: String(r.customer_id || ''), customer_name: String(o.customer_name || c.name || ''), customer_email: String(o.customer_email || c.email || ''),
    returns_90d: num(c.returns_last_90d), total_orders: num(c.total_orders), total_returns: num(c.total_returns), ltv: num(c.lifetime_value_inr), cust_flag: String(c.flag || '') });
});
const batch = open.slice(0, num(cfg.max_per_run) || 10);
let blob = '';
batch.forEach(b => { blob += '=== REQUEST ' + b.request_id + ' ===\nPRODUCT: ' + b.product_name + ' (' + b.category + '), Rs ' + b.order_value + ', paid by ' + b.payment_mode + '\nDELIVERED: ' + b.days_since_delivery + ' days ago\nIMAGES ATTACHED: ' + b.images_attached + '\nCUSTOMER WROTE: ' + b.raw_text + '\n\n'; });
return [{ json: { policy: P, requests: batch, open_count: batch.length, skipped: skipped, request_blob: blob || 'none',
  today: today, stamp: stamp, total_requests: reqs.length, data_issues: issues,
  write_back: (String(cfg.write_back_enabled) === 'true') || (cfg.write_back_enabled === true),
  brand_name: cfg.brand_name, support_name: cfg.support_name, ops_email: cfg.ops_email, support_phone: cfg.support_phone, loyal_ltv: num(cfg.loyal_ltv_inr) } }];

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
const parseJson = (raw) => { let t = String(raw || '').trim(); const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s !== -1 && e !== -1) t = t.slice(s, e + 1); t = t.replace(/,(\s*[}\]])/g, '$1'); try { return JSON.parse(t); } catch (err) { return null; } };
const A = $('Assemble Request Context').first().json;
const num = (v) => { const n = Number(v); return isFinite(n) ? n : 0; };
const P = A.policy || {};
const parsed = parseJson(textOf($input.first().json)) || {};
const cls = Array.isArray(parsed.requests) ? parsed.requests : [];
const pendingCount = (A.requests || []).length;
const aiOk = cls.length > 0;
const issues = Array.isArray(A.data_issues) ? A.data_issues.slice(0) : [];
if (!aiOk && pendingCount > 0) { issues.push('Reason classifier returned nothing for ' + pendingCount + ' open request(s), they all fell back to manual review'); }
const clsBy = {};
cls.forEach(c => { clsBy[String(c.request_id || '').trim()] = c; });
const abuseCount = num(P.abuse_return_count) || 3;
const abuseWindow = num(P.abuse_window_days) || 90;
const out = [];
(Array.isArray(A.requests) ? A.requests : []).forEach(r => {
  const c = clsBy[r.request_id] || {};
  const reason = String(c.reason_category || 'other').toLowerCase().trim();
  let risk = 0;
  const flags = [];
  if (r.returns_90d >= abuseCount) { risk += 45; flags.push(r.returns_90d + ' returns in the last ' + abuseWindow + ' days, above the limit of ' + abuseCount); }
  else if (r.returns_90d === abuseCount - 1) { risk += 20; flags.push(r.returns_90d + ' returns in the last ' + abuseWindow + ' days, one below the limit'); }
  const rate = r.total_orders > 0 ? r.total_returns / r.total_orders : 0;
  if (rate >= 0.5 && r.total_orders >= 4) { risk += 25; flags.push(Math.round(rate * 100) + ' percent of their orders end in a return'); }
  if (String(r.cust_flag).toLowerCase() === 'watch') { risk += 20; flags.push('Already flagged for watching by the team'); }
  if (r.payment_mode === 'cod' && reason === 'changed_mind') { risk += 10; flags.push('COD order with a change of mind claim'); }
  if (reason === 'damaged' && r.images_attached !== 'yes') { risk += 15; flags.push('Damage claimed with no image attached'); }
  if (r.ltv >= num(A.loyal_ltv) || String(r.cust_flag).toLowerCase() === 'loyal') { risk -= 20; flags.push('High value customer, lifetime spend Rs ' + r.ltv); }
  risk = Math.max(0, Math.min(100, risk));
  const band = risk >= 55 ? 'HIGH' : (risk >= 30 ? 'MEDIUM' : 'LOW');
  out.push(Object.assign({}, r, { reason_category: reason, reason_detail: String(c.reason_detail || ''), evidence_claimed: String(c.evidence_claimed || 'no').toLowerCase().trim(), sentiment: String(c.sentiment || 'calm'), language: String(c.language || 'english'), wants: String(c.wants || 'unclear'), ai_summary: String(c.summary || ''), risk_score: risk, risk_band: band, risk_flags: flags, classified: !!c.reason_category }));
});
return [{ json: { scored: out, ai_ok: aiOk, data_issues: issues } }];

const A = $('Assemble Request Context').first().json;
const S = $input.first().json;
const num = (v) => { const n = Number(v); return isFinite(n) ? n : 0; };
const P = A.policy || {};
const yes = (v) => String(v || '').toLowerCase().trim() === 'yes';
const retWindow = num(P.return_window_days) || 7;
const excWindow = num(P.exchange_window_days) || 14;
const nonRet = String(P.non_returnable_categories || '').toLowerCase().split(',').map(x => x.trim()).filter(x => x);
const needPhoto = yes(P.damaged_requires_photo);
const autoUnder = num(P.auto_approve_under_inr) || 0;
const pickupAbove = num(P.pickup_required_above_inr) || 999999;
const refundPrepaid = String(P.refund_mode_prepaid || 'original payment method');
const refundCod = String(P.refund_mode_cod || 'bank transfer');
const wrongAuto = yes(P.wrong_item_auto_approve);
const lateDays = num(P.late_delivery_days) || 10;
const restock = num(P.restocking_fee_pct) || 0;
const out = [];
let approved = 0, rejected = 0, manual = 0, evidence = 0;
let refundTotal = 0, cogsAtRisk = 0;
(Array.isArray(S.scored) ? S.scored : []).forEach(r => {
  const why = [];
  let decision = '';
  let refund = 0;
  let pickup = false;
  let refundMode = r.payment_mode === 'cod' ? refundCod : refundPrepaid;
  const reason = r.reason_category;
  const withinRet = r.days_since_delivery >= 0 && r.days_since_delivery <= retWindow;
  const withinExc = r.days_since_delivery >= 0 && r.days_since_delivery <= excWindow;
  const isNonRet = r.returnable === 'no' || nonRet.indexOf(String(r.category).toLowerCase()) !== -1;
  if (isNonRet) {
    decision = 'reject';
    why.push(r.category + ' is a non returnable category under the current policy');
  } else if (reason === 'wrong_item' && wrongAuto) {
    decision = 'refund';
    refund = r.order_value;
    pickup = true;
    why.push('Wrong item shipped, this is our error so policy says approve without argument');
    why.push('Pickup raised so the original item comes back');
  } else if (r.risk_band === 'HIGH') {
    decision = 'manual_review';
    why.push('Risk score ' + r.risk_score + ' out of 100, above the review threshold');
    (r.risk_flags || []).forEach(f => { why.push(f); });
  } else if (reason === 'late_delivery' && r.transit_days >= lateDays) {
    decision = 'refund';
    refund = r.order_value;
    pickup = r.order_value >= pickupAbove;
    why.push('Took ' + r.transit_days + ' days in transit against a ' + lateDays + ' day service promise');
    why.push('Counted as a service failure, not a customer change of mind');
  } else if (reason === 'damaged' && needPhoto && r.images_attached !== 'yes' && r.evidence_claimed !== 'yes') {
    decision = 'pending_evidence';
    why.push('Damage claimed but no image attached, and policy requires a photo');
  } else if (reason === 'damaged') {
    decision = 'refund';
    refund = r.order_value;
    pickup = r.order_value >= pickupAbove;
    why.push('Damage evidenced, approved under the damaged goods clause');
    if (pickup) { why.push('Value Rs ' + r.order_value + ' is above the Rs ' + pickupAbove + ' pickup threshold'); }
  } else if (reason === 'size' && withinExc) {
    decision = 'replacement';
    pickup = true;
    why.push('Size exchange requested ' + r.days_since_delivery + ' days after delivery, inside the ' + excWindow + ' day exchange window');
    why.push('Replacement sent, original collected on the same trip');
  } else if (reason === 'quality_defect' && withinRet) {
    decision = r.order_value >= pickupAbove ? 'pickup_and_inspect' : 'refund';
    if (decision === 'refund') { refund = r.order_value; }
    why.push('Quality complaint inside the ' + retWindow + ' day window');
    why.push(decision === 'refund' ? ('Value Rs ' + r.order_value + ' is under the Rs ' + pickupAbove + ' threshold, refunded without inspection to save cost') : ('Value Rs ' + r.order_value + ' needs the item back for QC before refund'));
    if (decision === 'pickup_and_inspect') { pickup = true; }
  } else if (!withinRet && reason !== 'size') {
    decision = 'reject';
    why.push('Raised ' + r.days_since_delivery + ' days after delivery, outside the ' + retWindow + ' day return window');
  } else if (!withinExc && reason === 'size') {
    decision = 'reject';
    why.push('Raised ' + r.days_since_delivery + ' days after delivery, outside the ' + excWindow + ' day exchange window');
  } else if (reason === 'changed_mind') {
    decision = 'refund';
    refund = Math.round(r.order_value * (1 - restock / 100));
    pickup = r.order_value >= pickupAbove;
    why.push('Change of mind inside the ' + retWindow + ' day window');
    if (restock > 0) { why.push(restock + ' percent restocking fee applied'); }
  } else {
    decision = 'manual_review';
    why.push('Reason did not match any policy rule cleanly, sending to a human');
  }
  if (decision === 'refund' && r.order_value < autoUnder) { pickup = false; why.push('Under the Rs ' + autoUnder + ' auto approve line, no pickup raised because collection would cost more than the item'); }
  let exception = false;
  if (decision === 'reject' && (String(r.cust_flag).toLowerCase() === 'loyal' || r.ltv >= num(A.loyal_ltv))) { exception = true; why.push('Policy says reject, but this customer has spent Rs ' + r.ltv + ' with us. Worth a human deciding whether to make an exception.'); }
  const countsAsReturn = (decision === 'refund' || decision === 'replacement' || decision === 'pickup_and_inspect');
  if (countsAsReturn) { approved += 1; if (decision === 'replacement') { cogsAtRisk += r.cogs; } else { refundTotal += refund; } }
  else if (decision === 'reject') { rejected += 1; }
  else if (decision === 'manual_review') { manual += 1; }
  else if (decision === 'pending_evidence') { evidence += 1; }
  out.push(Object.assign({}, r, { decision: decision, refund_amount: refund, refund_mode: refundMode, pickup_required: pickup, exception_suggested: exception, counts_as_return: countsAsReturn, decision_reasons: why, decision_reasons_text: why.join('; ') }));
});
let lines = '';
out.forEach((r, i) => { lines += (i + 1) + '. ' + r.request_id + ' | ' + r.customer_name + ' | ' + r.product_name + ' Rs ' + r.order_value + ' | reason: ' + r.reason_category + ' | DECISION: ' + r.decision + (r.refund_amount ? (' Rs ' + r.refund_amount) : '') + (r.pickup_required ? ' + pickup' : '') + ' | language: ' + r.language + ' | sentiment: ' + r.sentiment + ' | why: ' + r.decision_reasons_text + '\n'; });
return [{ json: { decided: out, decided_count: out.length, approved: approved, rejected: rejected, manual: manual, evidence: evidence,
  refund_total: refundTotal, cogs_at_risk: cogsAtRisk, decision_lines: lines || 'none',
  ai_ok: S.ai_ok, data_issues: S.data_issues } }];

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
const parseJson = (raw) => { let t = String(raw || '').trim(); const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s !== -1 && e !== -1) t = t.slice(s, e + 1); t = t.replace(/,(\s*[}\]])/g, '$1'); try { return JSON.parse(t); } catch (err) { return null; } };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const A = $('Assemble Request Context').first().json;
const D = $('Policy Engine').first().json;
const parsed = parseJson(textOf($input.first().json)) || {};
const reps = Array.isArray(parsed.replies) ? parsed.replies : [];
const repBy = {};
reps.forEach(r => { repBy[String(r.request_id || '').trim()] = r; });
const INDIGO = '#1F2A44', SAFFRON = '#C86B2B', CREAM = '#FBF6EF', WHITE = '#FFFFFF', INK = '#1A1A1A', GREY = '#6A6A6A', GREEN = '#1B7E42';
const labelOf = (d) => { if (d === 'refund') { return 'REFUND APPROVED'; } if (d === 'replacement') { return 'EXCHANGE CONFIRMED'; } if (d === 'reject') { return 'ABOUT YOUR REQUEST'; } if (d === 'pending_evidence') { return 'ONE THING NEEDED'; } if (d === 'manual_review') { return 'WE ARE ON IT'; } return 'PICKUP SCHEDULED'; };
const accentOf = (d) => { if (d === 'refund' || d === 'replacement') { return '#7FD6A0'; } if (d === 'reject') { return '#C9C3BA'; } return '#F0C078'; };
const out = [];
(Array.isArray(D.decided) ? D.decided : []).forEach(r => {
  if (!r.customer_email) { return; }
  const rep = repBy[r.request_id] || {};
  const subject = rep.subject || (r.decision === 'reject' ? ('About your return request') : ('Update on your ' + r.product_name));
  const lines = Array.isArray(rep.lines) && rep.lines.length ? rep.lines : ['We have reviewed your request and our team will be in touch shortly.'];
  const nextStep = rep.next_step || 'Our team will contact you if anything else is needed.';
  let body = '';
  lines.forEach(l => { body += '<div style="font-size:15.5px;color:' + INK + ';line-height:1.65;margin-bottom:10px;">' + esc(l) + '</div>'; });
  let detailRow = '';
  if (r.decision === 'refund' && r.refund_amount > 0) {
    detailRow = '<tr><td style="padding:6px 26px 12px 26px;"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E6DED2;border-radius:8px;border-left:4px solid ' + GREEN + ';background:' + CREAM + ';">' +
    '<tr><td style="padding:12px 15px;font-size:12.5px;color:' + GREY + ';">Refund amount</td><td align="right" style="padding:12px 15px;font-size:18px;font-weight:bold;color:' + GREEN + ';">Rs ' + esc(r.refund_amount) + '</td></tr>' +
    '<tr><td style="padding:12px 15px;font-size:12.5px;color:' + GREY + ';border-top:1px solid #E6DED2;">Sent to</td><td align="right" style="padding:12px 15px;font-size:13.5px;color:' + INDIGO + ';border-top:1px solid #E6DED2;">' + esc(r.refund_mode) + '</td></tr>' +
    (r.pickup_required ? ('<tr><td style="padding:12px 15px;font-size:12.5px;color:' + GREY + ';border-top:1px solid #E6DED2;">Pickup</td><td align="right" style="padding:12px 15px;font-size:13.5px;color:' + INDIGO + ';border-top:1px solid #E6DED2;">Our courier will collect the item</td></tr>') : '') +
    '</table></td></tr>';
  } else if (r.decision === 'replacement') {
    detailRow = '<tr><td style="padding:6px 26px 12px 26px;"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E6DED2;border-radius:8px;border-left:4px solid ' + GREEN + ';background:' + CREAM + ';">' +
    '<tr><td style="padding:12px 15px;font-size:12.5px;color:' + GREY + ';">Item</td><td align="right" style="padding:12px 15px;font-size:13.5px;font-weight:bold;color:' + INDIGO + ';">' + esc(r.product_name) + '</td></tr>' +
    '<tr><td style="padding:12px 15px;font-size:12.5px;color:' + GREY + ';border-top:1px solid #E6DED2;">Exchange</td><td align="right" style="padding:12px 15px;font-size:13.5px;color:' + INDIGO + ';border-top:1px solid #E6DED2;">New size dispatched, original collected on the same trip</td></tr>' +
    '</table></td></tr>';
  }
  const html = '<div style="background:' + CREAM + ';padding:22px;font-family:Calibri,Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;background:' + WHITE + ';border-radius:10px;overflow:hidden;">' +
  '<tr><td style="background:' + INDIGO + ';padding:22px 26px;"><div style="color:' + accentOf(r.decision) + ';font-size:11px;font-weight:bold;letter-spacing:3px;">' + labelOf(r.decision) + '</div>' +
  '<div style="color:' + WHITE + ';font-family:Georgia,serif;font-size:23px;font-weight:bold;margin-top:6px;">' + esc(A.brand_name) + '</div>' +
  '<div style="color:#B9C2D4;font-size:12.5px;margin-top:4px;">Order ' + esc(r.order_id) + ' &middot; ' + esc(r.product_name) + '</div></td></tr>' +
  '<tr><td style="padding:22px 26px 6px 26px;"><div style="font-size:16px;font-weight:bold;color:' + INK + ';margin-bottom:12px;">Hi ' + esc(r.customer_name) + ',</div>' + body + '</td></tr>' + detailRow +
  '<tr><td style="padding:6px 26px 14px 26px;"><div style="background:#F4EFE7;border-radius:7px;padding:12px 14px;font-size:13.5px;color:' + INK + ';"><strong>What happens next.</strong> ' + esc(nextStep) + '</div></td></tr>' +
  '<tr><td style="padding:4px 26px 20px 26px;"><div style="font-size:14px;color:' + INK + ';">Warmly,</div><div style="font-size:14px;color:' + INK + ';font-weight:bold;">' + esc(A.support_name) + '</div><div style="font-size:13px;color:' + GREY + ';">' + esc(A.brand_name) + ' &middot; ' + esc(A.support_phone) + '</div></td></tr>' +
  '</table></div>';
  out.push({ json: { to: r.customer_email, subject: subject, html: html, request_id: r.request_id, order_id: r.order_id, customer_id: r.customer_id, customer_name: r.customer_name, sku: r.sku, reason_category: r.reason_category, decision: r.decision, refund_amount: r.refund_amount, risk_score: r.risk_score, reasons: r.decision_reasons_text, run_date: A.today, counts_as_return: r.counts_as_return, reply_ok: !!rep.subject } });
});
return out;

const A = $('Assemble Request Context').first().json;
if (!A.write_back) { return []; }
const rows = $input.all().map(i => i.json).filter(r => r && r.counts_as_return);
if (rows.length === 0) { return []; }
const num = (v) => { const n = Number(v); return isFinite(n) ? n : 0; };
const uniq = (arr, key) => { const seen = {}; const out = []; arr.forEach(r => { const k = String(r[key] || '').trim(); if (k && !seen[k]) { seen[k] = true; out.push(r); } }); return out; };
const custs = uniq($('Read Customers').all().map(i => i.json).filter(r => r && r.customer_id), 'customer_id');
const custBy = {};
custs.forEach(c => { custBy[String(c.customer_id).trim()] = c; });
const tally = {};
rows.forEach(r => { const cid = String(r.customer_id || '').trim(); if (!cid) { return; } tally[cid] = (tally[cid] || 0) + 1; });
const out = [];
Object.keys(tally).forEach(cid => {
  const c = custBy[cid];
  if (!c) { return; }
  out.push({ json: { customer_id: cid, total_returns: num(c.total_returns) + tally[cid], returns_last_90d: num(c.returns_last_90d) + tally[cid], added: tally[cid], name: String(c.name || '') } });
});
return out;

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const A = $('Assemble Request Context').first().json;
const D = $('Policy Engine').first().json;
const INDIGO = '#1F2A44', SAFFRON = '#C86B2B', CREAM = '#FBF6EF', WHITE = '#FFFFFF', INK = '#1A1A1A', GREY = '#6A6A6A', GREEN = '#1B7E42', RED = '#C0392B', AMBER = '#E08A1E';
const issues = Array.isArray(D.data_issues) ? D.data_issues.slice(0) : [];
let banner = '';
if (issues.length) { banner = '<tr><td style="padding:12px 26px 0 26px;"><div style="background:#FBE9E7;border-left:4px solid ' + RED + ';border-radius:6px;padding:11px 13px;font-size:12.5px;color:#7A1F14;"><strong>Heads up.</strong> ' + esc(issues.slice(0, 3).join('; ')) + '</div></td></tr>'; }
const colOf = (d) => { if (d === 'refund' || d === 'replacement') { return GREEN; } if (d === 'reject') { return GREY; } if (d === 'manual_review') { return RED; } return AMBER; };
const dec = Array.isArray(D.decided) ? D.decided : [];
if (dec.length === 0) {
  const quiet = '<div style="background:' + CREAM + ';padding:22px;font-family:Calibri,Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;margin:0 auto;background:' + WHITE + ';border-radius:10px;overflow:hidden;">' +
  '<tr><td style="background:' + INDIGO + ';padding:24px 26px;"><div style="color:' + SAFFRON + ';font-size:11px;font-weight:bold;letter-spacing:3px;">RETURNS DESK</div>' +
  '<div style="color:' + WHITE + ';font-family:Georgia,serif;font-size:25px;font-weight:bold;margin-top:7px;">Nothing new to decide</div>' +
  '<div style="color:#B9C2D4;font-size:13px;margin-top:5px;">' + esc(A.today) + ' &middot; ' + esc(A.skipped) + ' request(s) already decided on an earlier run</div></td></tr>' +
  '<tr><td style="padding:20px 26px;"><div style="font-size:14.5px;color:' + INK + ';line-height:1.6;">Every open request in the sheet has already been processed and the customer informed. Nothing was sent again.</div></td></tr>' +
  '<tr><td style="background:' + INDIGO + ';padding:12px 26px;"><div style="color:#8C97AD;font-size:11px;">' + esc(A.brand_name) + ' &middot; Returns Control Desk &middot; Powered by Haus of Intelligence</div></td></tr></table></div>';
  return [{ json: { digest_html: quiet, decided_count: 0, approved: 0, refund_total: 0, ops_email: A.ops_email, today: A.today } }];
}
const pickups = dec.filter(r => r.pickup_required);
const exceptions = dec.filter(r => r.exception_suggested);
const manualOnes = dec.filter(r => r.decision === 'manual_review');
let cards = '';
dec.forEach(r => {
  let whyHtml = '';
  (r.decision_reasons || []).forEach(w => { whyHtml += '<li style="margin-bottom:4px;">' + esc(w) + '</li>'; });
  cards += '<tr><td style="padding:0 26px 13px 26px;"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E6DED2;border-radius:8px;border-left:4px solid ' + colOf(r.decision) + ';background:#FFFFFF;">' +
  '<tr><td style="padding:13px 15px 4px 15px;"><table width="100%" cellpadding="0" cellspacing="0"><tr>' +
  '<td><div style="font-family:Georgia,serif;font-size:16.5px;font-weight:bold;color:' + INDIGO + ';">' + esc(r.customer_name) + '</div>' +
  '<div style="font-size:12px;color:' + GREY + ';margin-top:3px;">' + esc(r.product_name) + ' &middot; Rs ' + esc(r.order_value) + ' &middot; ' + esc(r.payment_mode) + ' &middot; ' + esc(r.request_id) + '</div></td>' +
  '<td align="right"><div style="display:inline-block;background:' + colOf(r.decision) + ';color:#FFFFFF;font-size:10.5px;font-weight:bold;padding:4px 10px;border-radius:4px;">' + esc(String(r.decision).replace(/_/g, ' ').toUpperCase()) + '</div>' +
  (r.refund_amount > 0 ? ('<div style="font-size:15px;font-weight:bold;color:' + GREEN + ';margin-top:5px;">Rs ' + esc(r.refund_amount) + '</div>') : '') + '</td>' +
  '</tr></table></td></tr>' +
  '<tr><td style="padding:4px 15px 4px 15px;"><table width="100%" cellpadding="0" cellspacing="0"><tr>' +
  '<td style="font-size:12px;color:' + INK + ';">reason: <strong>' + esc(r.reason_category) + '</strong></td>' +
  '<td style="font-size:12px;color:' + INK + ';">delivered ' + esc(r.days_since_delivery) + 'd ago</td>' +
  '<td style="font-size:12px;color:' + INK + ';">risk ' + esc(r.risk_score) + ' ' + esc(r.risk_band) + '</td>' +
  '<td style="font-size:12px;color:' + INK + ';">' + (r.pickup_required ? 'pickup needed' : 'no pickup') + '</td>' +
  '</tr></table></td></tr>' +
  '<tr><td style="padding:4px 15px 6px 15px;"><div style="font-size:12.5px;color:' + GREY + ';font-style:italic;">“' + esc(String(r.raw_text).slice(0, 150)) + '”</div></td></tr>' +
  (whyHtml ? ('<tr><td style="padding:2px 15px 12px 15px;"><div style="background:' + CREAM + ';border-radius:6px;padding:10px 12px;"><div style="font-size:10.5px;font-weight:bold;color:' + GREY + ';letter-spacing:1px;">WHY THIS DECISION</div><ul style="font-size:12.5px;color:' + INK + ';line-height:1.45;margin:6px 0 0 0;padding-left:18px;">' + whyHtml + '</ul></div></td></tr>') : '') +
  (r.exception_suggested ? ('<tr><td style="padding:0 15px 12px 15px;"><div style="background:#FFF4E0;border-left:3px solid ' + AMBER + ';border-radius:5px;padding:9px 12px;font-size:12.5px;color:#7A4A10;"><strong>Worth a human call.</strong> Lifetime spend Rs ' + esc(r.ltv) + '. The policy rejects this, you may not want to.</div></td></tr>') : '') +
  '</table></td></tr>';
});
let pickHtml = '';
pickups.forEach(r => { pickHtml += '<tr><td style="padding:8px 12px;border-bottom:1px solid #E6DED2;font-size:12.5px;color:' + INK + ';"><strong>' + esc(r.customer_name) + '</strong><br><span style="color:' + GREY + ';font-size:11px;">' + esc(r.city) + ' ' + esc(r.pincode) + '</span></td><td style="padding:8px 12px;border-bottom:1px solid #E6DED2;font-size:12.5px;color:' + INK + ';">' + esc(r.product_name) + '</td><td align="right" style="padding:8px 12px;border-bottom:1px solid #E6DED2;font-size:12px;color:' + GREY + ';">' + esc(r.courier) + '</td></tr>'; });
const html = '<div style="background:' + CREAM + ';padding:22px;font-family:Calibri,Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="max-width:700px;margin:0 auto;background:' + WHITE + ';border-radius:10px;overflow:hidden;">' +
'<tr><td style="background:' + INDIGO + ';padding:24px 26px;"><div style="color:' + SAFFRON + ';font-size:11px;font-weight:bold;letter-spacing:3px;">RETURNS DESK</div>' +
'<div style="color:' + WHITE + ';font-family:Georgia,serif;font-size:26px;font-weight:bold;margin-top:7px;">' + esc(D.decided_count) + ' request(s) decided</div>' +
'<div style="color:#B9C2D4;font-size:13px;margin-top:5px;">' + esc(A.today) + ' &middot; every decision taken against your written policy</div></td></tr>' + banner +
'<tr><td style="padding:18px 26px 4px 26px;"><table width="100%" cellpadding="0" cellspacing="0"><tr>' +
'<td align="center" style="background:' + GREEN + ';border-radius:6px;padding:14px 6px;"><div style="color:#FFFFFF;font-family:Georgia,serif;font-size:24px;font-weight:bold;">' + esc(D.approved) + '</div><div style="color:#D6EBDD;font-size:10px;">approved</div></td><td width="7"></td>' +
'<td align="center" style="background:' + CREAM + ';border-radius:6px;padding:14px 6px;"><div style="color:' + GREY + ';font-family:Georgia,serif;font-size:24px;font-weight:bold;">' + esc(D.rejected) + '</div><div style="color:' + GREY + ';font-size:10px;">rejected</div></td><td width="7"></td>' +
'<td align="center" style="background:' + RED + ';border-radius:6px;padding:14px 6px;"><div style="color:#FFFFFF;font-family:Georgia,serif;font-size:24px;font-weight:bold;">' + esc(D.manual) + '</div><div style="color:#F5D5D0;font-size:10px;">manual review</div></td><td width="7"></td>' +
'<td align="center" style="background:' + CREAM + ';border-radius:6px;padding:14px 6px;"><div style="color:' + INDIGO + ';font-family:Georgia,serif;font-size:20px;font-weight:bold;">Rs ' + esc(D.refund_total) + '</div><div style="color:' + GREY + ';font-size:10px;">refunds approved</div></td><td width="7"></td>' +
'<td align="center" style="background:' + CREAM + ';border-radius:6px;padding:14px 6px;"><div style="color:' + INDIGO + ';font-family:Georgia,serif;font-size:24px;font-weight:bold;">' + esc(pickups.length) + '</div><div style="color:' + GREY + ';font-size:10px;">pickups to raise</div></td>' +
'</tr></table></td></tr>' +
(manualOnes.length || exceptions.length ? ('<tr><td style="padding:16px 26px 4px 26px;"><div style="background:#FFF4E0;border-radius:8px;border-left:4px solid ' + AMBER + ';padding:13px 15px;"><div style="font-size:11px;font-weight:bold;color:#7A4A10;letter-spacing:1px;">NEEDS A HUMAN TODAY</div><div style="font-size:13.5px;color:#7A4A10;margin-top:6px;line-height:1.5;">' + esc(manualOnes.length) + ' held for review, ' + esc(exceptions.length) + ' rejection(s) where the customer is worth more than the policy.</div></div></td></tr>') : '') +
'<tr><td style="padding:16px 26px 8px 26px;"><div style="font-family:Georgia,serif;font-size:17px;font-weight:bold;color:' + INDIGO + ';">Every decision, with its reasoning</div></td></tr>' + cards +
(pickHtml ? ('<tr><td style="padding:10px 26px 18px 26px;"><div style="font-family:Georgia,serif;font-size:16px;font-weight:bold;color:' + INDIGO + ';margin-bottom:8px;">Pickups to raise with the courier</div><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E6DED2;border-radius:8px;">' + pickHtml + '</table></td></tr>') : '') +
